import _codecs
seen = []
class Position:
    def __init__(self, error):
        self.error = error
    def __index__(self):
        seen.append(input())
        self.error.object = b'Z\u0041'
        return -6
def recover(error):
    seen.append((error.encoding, error.object, error.start, error.end, error.reason))
    return ('?', Position(error))
_codecs.register_error('edge-resume', recover)
print(_codecs.unicode_escape_decode(b'\uQ', 'edge-resume', False))
print(seen)

