import sys,json,codecs,warnings,unicodedata
fixture=json.load(sys.stdin)
def run_decode(row):
 with warnings.catch_warnings(record=True) as caught:
  warnings.simplefilter('always')
  try:
   text,consumed=getattr(codecs,'raw_unicode_escape_decode' if row['raw'] else 'unicode_escape_decode')(bytes(row['input']),row['errors'],row['final'])
   result={'result':[[ord(c) for c in text],consumed]}
  except UnicodeDecodeError as e:
   result={'error':[e.encoding,list(e.object),e.start,e.end,e.reason]}
  result['warnings']=[[w.category.__name__,str(w.message)] for w in caught]
  return result
def run_incremental(row):
 decoder=codecs.getincrementaldecoder('raw_unicode_escape' if row['raw'] else 'unicode_escape')(row['errors'])
 data=bytes(row['input']);results=[]
 for index,chunk in enumerate((data[:row['split']],data[row['split']:])):
  with warnings.catch_warnings(record=True) as caught:
   warnings.simplefilter('always')
   try: result={'result':[ord(c) for c in decoder.decode(chunk,index==1)]}
   except UnicodeDecodeError as e: result={'error':[e.encoding,list(e.object),e.start,e.end,e.reason]}
   pending,flag=decoder.getstate()
   result['state']=[list(pending),flag]
   result['warnings']=[[w.category.__name__,str(w.message)] for w in caught]
   results.append(result)
 return results
json.dump({'reference':{'version':sys.version,'unicode':unicodedata.unidata_version,'platform':sys.platform,'byteorder':sys.byteorder},'decode':[run_decode(r) for r in fixture['decode']],'incremental':[run_incremental(r) for r in fixture['incremental']],'encode':[list(''.join(chr(p) for p in r['input']).encode('raw_unicode_escape' if r['raw'] else 'unicode_escape')) for r in fixture['encode']]},sys.stdout)
